CREATE TABLE IF NOT EXISTS terminology_resource (scope_id TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, canonical_url TEXT NOT NULL, version TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '', resource_json BLOB NOT NULL, content_mode TEXT NOT NULL DEFAULT '', source_module TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(scope_id,resource_type,canonical_url,version));
CREATE TABLE IF NOT EXISTS terminology_concept (scope_id TEXT NOT NULL, system_url TEXT NOT NULL, system_version TEXT NOT NULL DEFAULT '', code TEXT NOT NULL, display TEXT NOT NULL DEFAULT '', definition TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, abstract INTEGER NOT NULL DEFAULT 0, parent_code TEXT NOT NULL DEFAULT '', properties_json TEXT NOT NULL DEFAULT '', designations_json TEXT NOT NULL DEFAULT '', PRIMARY KEY(scope_id,system_url,system_version,code));
CREATE TABLE IF NOT EXISTS terminology_valueset (scope_id TEXT NOT NULL, canonical_url TEXT NOT NULL, version TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '', compose_json TEXT NOT NULL DEFAULT '', expansion_json BLOB, expansion_timestamp TEXT NOT NULL DEFAULT '', expansion_fingerprint TEXT NOT NULL DEFAULT '', PRIMARY KEY(scope_id,canonical_url,version));
CREATE TABLE IF NOT EXISTS terminology_expansion_member (scope_id TEXT NOT NULL, valueset_url TEXT NOT NULL, valueset_version TEXT NOT NULL DEFAULT '', system_url TEXT NOT NULL, system_version TEXT NOT NULL DEFAULT '', code TEXT NOT NULL, display TEXT NOT NULL DEFAULT '', inactive INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(scope_id,valueset_url,valueset_version,system_url,system_version,code));
